"""Render the separate controlled-furrowing dossier with local mathematical assets."""
from pathlib import Path
import html
import json
import re
import markdown

ROOT=Path(__file__).resolve().parents[1]
DOC=ROOT/"docs"


def convert(text):
    # Markdown tables otherwise tokenize literal | even inside HTML attributes.
    # The browser decodes this entity back to the original TeX before KaTeX.
    attribute=lambda tex:html.escape(tex,quote=True).replace('|','&#124;')
    text=re.sub(r"\\\[(.*?)\\\]",lambda m:'\n<div class="math display" data-tex="'+attribute(m[1])+'"></div>\n',text,flags=re.S)
    text=re.sub(r"\\\((.*?)\\\)",lambda m:'<span class="math" data-tex="'+attribute(m[1])+'"></span>',text,flags=re.S)
    def local_page_link(match):
        target=(DOC/(match[1]+'.md')).resolve()
        return ']('+match[1]+'.html)' if target.exists() and target.parent==DOC.resolve() else match[0]
    text=re.sub(r'\]\(([^():]+)\.md\)',local_page_link,text)
    return markdown.markdown(text,extensions=["tables","fenced_code"])


def shell(title,body):
    css="""*{box-sizing:border-box}body{margin:0;background:#0b111b;color:#e7eef7;font:17px/1.65 system-ui,sans-serif;overflow-wrap:anywhere}main{max-width:1120px;margin:auto;padding:36px 24px 80px}h1,h2,h3{line-height:1.2}h1{font-size:clamp(2rem,5vw,3.6rem)}h2{margin-top:2em;color:#aedbe8}a{color:#8ad4ef}nav{display:flex;gap:12px 24px;flex-wrap:wrap;padding-bottom:18px;border-bottom:1px solid #354357}img{max-width:100%;height:auto}table{border-collapse:collapse;display:block;overflow:auto;font-size:.9em}th,td{padding:12px;border:1px solid #33435a;vertical-align:top}pre,.math.display{overflow:auto;padding:15px;background:#111e30}code{overflow-wrap:anywhere}.status{border:1px solid #9d8044;border-left:5px solid #e3ba66;padding:18px;margin:24px 0;background:#172030}#math-errors{color:#ff9999}li{margin:.4em 0}@media(max-width:600px){body{font-size:16px}main{padding:24px 14px}}"""
    return '<!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>'+html.escape(title)+'</title><link rel="stylesheet" href="../../docs/assets/katex/katex.min.css"><style>'+css+'</style></head><body><main><nav><a href="index.html">Controlled furrowing</a><a href="ORIGINALITY.html">Originality</a><a href="DATA.html">Data</a><a href="MODEL-CANDIDATES.html">Mechanics</a><a href="SLICE-OBSERVER.html">Slice observation</a><a href="../../docs/index.html">Parent dossier</a></nav>'+body+'<p id="math-errors"></p></main><script src="../../docs/assets/katex/katex.min.js"></script><script>document.querySelectorAll(".math").forEach(e=>{try{katex.render(e.dataset.tex,e,{displayMode:e.classList.contains("display"),throwOnError:true})}catch(x){document.getElementById("math-errors").textContent+=String(x)}});</script></body></html>'


def main():
    for path in DOC.glob("*.md"):
        (DOC/(path.stem+".html")).write_text(shell(path.stem,convert(path.read_text(encoding="utf-8"))),encoding="utf-8")
    ledger=json.loads((ROOT/"evidence/gates.json").read_text(encoding="utf-8"))
    score=json.loads((ROOT/"evidence/scalar_scores.json").read_text(encoding="utf-8"))
    body='<p>PROJECT 4 · CONTROLLED FURROWING · EVIDENCE DOSSIER</p><h1>Can local contraction predict tissue geometry?</h1><div class="status"><strong>FIVE-GATE STUDY IN PROGRESS</strong><p>The first coupled finite-height model was calibrated and tested through declared mechanical proxies. Revised numerical models and a current-radius observation operator are implemented; all-four-observable candidate replay is complete, with substantial discrepancies in the fixed material scenario. Full multivariate inference remains in progress. Source aggregation/reference ambiguities and full parameter-set propagation remain unresolved. No confirmed novel concept or specimen-resolved shape prediction is established.</p></div>'
    body+='<p>The target is one finite-height mechanical model calibrated only on small activated regions, then tested on larger regions without fitting their outcomes. The known size effect and basal-stiffness mechanism are already published. <a href="ORIGINALITY.html">Read the exact originality audit</a>.</p>'
    body+='<h2>New: exact integration blocks unchanged certificate transfer</h2><p>All144 bulk elements and24 surface edges are bounded at one saved B-center field. With the old preconditioner, the exact-integral map displaces the old center by more than1.6208e-11, beyond its1e-11 proof-cube radius. The cached-quadrature proofs remain valid for their original target; an exact-integral equilibrium is not ruled out. <a href="EXACT-INTEGRATION-BRIDGE.html">Full derivation, two visuals and independent receipts</a>. Uniform map/center/domain bounds, continuum accuracy, source-matched inference and novelty remain incomplete.</p>'
    body+='<h2>New: the public-source audit and the remaining data dependency</h2><p>All16 linked supplementary assets match official checksums. Ten movies contain903 decoded frames; the36-page peer-review file and workbook package structures are audited. These sources constrain the protocol but do not supply the matched cohort geometry/reference/ROI and uncertainty contract. <a href="PUBLIC-SUPPLEMENT-AUDIT.html">Audit, original diagram and receipts</a>; <a href="DRAFT-DATA-REQUEST.html">prepared processed-data request, not sent</a>. The existing local energy-minimum proof and residual are unchanged; the five-gate study remains incomplete.</p>'
    body+='<h2>Mechanics checkpoint: all 17 selected states are local energy minima</h2><p><a href="COHORT-ENERGY-STABILITY.html">Proof, visual and independent matrix certificates</a>. Validated positivity of the exact numerical preconditioners, together with the existing uniform root bounds, proves positive reduced energy Hessians throughout all seventeen selected root tubes. These are strict local minima of the fixed finite-quadrature energy on the same tiny parameter cell. A common loading history, continuum stability, source-matched biological fit and novelty remain unresolved.</p>'
    body+='<h2>Previous checkpoint: all 68 static outputs on one shared parameter cell</h2><p><a href="SHARED-CELL-COHORT.html">Read the theorem, full-cohort visual and verification receipts</a>. Seventeen independently checked local stationary-root families now support 68 uniform output intervals on the SAME extremely small five-parameter box. Two cases required a single numerical-center correction; the physical potential, parameters, preconditioner and predictor stayed fixed. The worst-case residual D(theta) is safely enclosed by [5.18638714, 5.18638737]µm throughout that box. Illustrative 5.1/5.2µm allowances exclude/admit this selected stationary tuple. These are not measurement-noise estimates, a stable activation history, full identified-set inference or continuum accuracy. Source temporal/geometry matching and novelty remain unresolved.</p>'
    body+='<h2>Earlier: parameter families and one conditional exclusion</h2><p><a href="PARAMETER-INFERENCE-CHECKPOINT.html">Read the current checkpoint, proofs and remaining original requirements</a>. One old weak-load model has uniform local energy minima and globally injective bodies throughout a relative gain interval of ±0.1%. A different, extremely narrow five-coordinate cell at actual calibration record M has a certified static-apical response near6.81361µm against the reported12µm. Its selected nearby stationary family is excluded below approximately5.18638714µm declared apical discrepancy. This does not reject all branches or establish a noise estimate, all68 fit, continuum accuracy or novelty. At that earlier checkpoint the shared-cell all17 extension was being prepared; its current result is linked above. <a href="ACTUAL-M-CELL-EXCLUSION.html">Actual-M proof and finite-cover visual</a>; <a href="ENERGY-GAIN-CELL.html">energy-norm interval proof</a>; <a href="ENERGY-GAIN-GEOMETRY-REVIEW.html">independent geometry review</a>.</p>'
    body+='<h2>Completed candidate replay and material inference</h2><p>All 68 distinct nonlinear targets are complete and independently reviewed. Candidate discrepancies of 5.38–6.25 µm expose regional-mean and component mismatches in the fixed scenario. A local five-coordinate material/gain step uses all 17 records and all 68 endpoints. Its primary nonlinear replay improves the fixed-discrete discrepancy from 5.37984 to 5.18639 µm, while one other observation convention worsens. Gain changed jointly with material ratios; neither a gain-only advantage nor continuum robustness is established. <a href="MATERIAL-COHORT-DIRECT.html">Direct result and comparison visual</a>; <a href="MATERIAL-COHORT-DIRECT-REVIEW.html">independent 435-check replay</a>. <a href="JOINT-GAIN-CALIBRATION.html">Completed direct results and three figures</a>; <a href="PHYSICAL-INFERENCE-READINESS.html">physical inference prerequisites</a>; <a href="MATERIAL-TANGENT-INFERENCE.html">material sensitivities</a>; <a href="BOUNDED-AFFINE-MINIMAX.html">exact local LP certificates</a>.</p>'
    body+='<h2>Earlier: one archived discrete root and its error certificate</h2><p>A separate 256-bit interval-AD program rebuilds all 9,504 terms for one archived 611-variable weak-load state and proves a nearby locally unique stationary point. An exact nodal-to-observer argument, including serialization error, bounds the static height-endpoint algebraic-error contribution below 2.438e-10 µm. These small numbers measure agreement with the specified mathematical target, not biological precision. That one-field proof itself does not cover continuum error, stability, all seventeen new material fields or the compatible parameter domain; the later common-cell cohort is linked above. <a href="ALGEBRAIC-ROOT-CERTIFICATION-PATH.html">Proof and failed-radius visual</a>; <a href="ALGEBRAIC-ROOT-INDEPENDENT-REVIEW.html">independent reconstruction</a>; <a href="ALGEBRAIC-ROOT-OBSERVER-ERROR.html">actual observer-error application</a>; <a href="CURRENT-FIVE-GATE-AUDIT.html">original requirements still unfinished</a>.</p>'
    body+='<h2>Why observation summaries cannot replace mechanics</h2><p>Static regional means impose a sharp conditional compatibility floor. Separate peak times remove that identity: explicit volume-preserving paths match 16 records under both height averaging orders. The retained zero-mean/positive-maximum record is a nonattained boundary under mean-of-local-peaks, with zero approximation-error infimum. These constructions use independent paths, not one common force law or material fit. <a href="STATIC-MEAN-COMPATIBILITY.html">Static proof</a>; <a href="TEMPORAL-ORDER-ROBUST-WITNESS.html">temporal classification, proof and visual</a>; <a href="TEMPORAL-ORDER-ROBUST-REVIEW.html">independent 503-check review</a>.</p><img src="assets/temporal_order_robust_witness.png" alt="Constructed height profiles and exact nonattainment boundary; not measured tissue traces">'
    body+='<h2>What has actually been verified</h2><p>Public workbooks were downloaded and independently decoded: 4,786 nonempty cells across 40 sheets agree. Repeated small-region values are counted once. Scalar predictions were replayed with larger-region responses physically absent and reproduced byte for byte.</p>'
    body+='<table><tr><th>Model</th><th>Larger-region RMSE (µm), n=9</th></tr>'
    for name,label in [("primary_mechanical","Independent-column null"),("OLS","Calibration-only linear fit"),("zero_shortening","Zero shortening")]:
        body+='<tr><td>'+label+'</td><td>'+f'{score["scores"][name]["RMSE_um"]:.4f}'+'</td></tr>'
    body+='</table><p>These numbers concern maximum shortening, not curvature or furrow direction. The 0.23-µm difference between the two fitted curves is not evidence of a new mechanism or statistically established superiority.</p><img src="assets/scalar_reproduction.png" alt="Frozen scalar reproduction and all declared comparator errors">'
    body+='<h2>The first coupled model: retained proxy comparisons</h2><p>Three basal-area-stiffness scenarios fit small-region material-column shortening with RMSE 2.25–2.27 µm against the published maximum-shortening values. Their central motions are basal-dominant in 17/17 cases; the paired experimental component entries are apical-dominant in 16/17. These are different observation summaries, so the disagreement is an adequacy warning rather than a matched biological falsification. The larger-region scalar proxy errors are 3.05–3.15 µm, worse than the simple linear comparator. All 31 image-label sets allow both labels, so zero exclusions is not predictive accuracy. <a href="SPATIAL-V1-RESULTS.html">Historical calculations and limits</a>; <a href="JOINT-OBSERVATION-CONTRACT.html">new source-definition audit</a>.</p><img src="assets/spatial_transfer.png" alt="Historical coupled-model proxy errors and non-discriminating label comparison"><p>Exact rational geometry checks verify 144 saved discrete bodies, including noninterpenetration and Jacobian bounds. They also confirm local volume compression approaching 20 percent. Positive geometry and solver stationarity do not establish a physically adequate incompressibility approximation or continuum accuracy. <a href="DISCRETE-GEOMETRY-CERTIFICATE.html">Certificate and proof</a>.</p>'
    body+='<h2>Current calibration and numerical limits</h2><p><a href="READINESS-CHECKPOINT.html">Read the current findings and the original requirements still missing</a>. For fixed measured doses, a common nondecreasing response curve requires at least 3.131943715 µm worst-case discrepancy across the 17 small-region records. Allowing one hypothetical exception lowers this only to 3.084159745 µm. These are exact deterministic compatibility bounds, not estimates of measurement noise or reasons to remove embryos. Independent algorithms checked all 131,072 subsets. <a href="CALIBRATION-UNCERTAINTY.html">Proof and source definitions</a>; <a href="CALIBRATION-EXCEPTION-REVIEW.html">independent exception-budget replay</a>.</p><img src="../runs/calibration_uncertainty/compatibility_envelopes.png" alt="Small-region monotone compatibility envelopes, explicitly not statistical confidence bands">'
    body+='<p>Higher numerical integration changes the force equations enough that the former equilibria fail the higher-rule force check. Six corrected 12×6 fields pass both the new rule and a further-raised rule. At the preselected strong load, the corrected 12×6 and 16×8 apical curves still differ by an exact discrete Eulerian supremum in [0.749610, 0.757379] µm. This is an inter-mesh discrepancy, not a continuum error bound. <a href="ACTIVATED-QUADRATURE.html">Integration correction</a>; <a href="JOINT-REFINEMENT.html">joint mesh/integration study and receipts</a>.</p><img src="../runs/joint_refinement/joint-refinement.png" alt="Higher-integration 12×6 and 16×8 tissue surfaces and exact discrete difference enclosures">'
    body+='<p>A separately verified sparse Newton method permits finer calculations while preserving the physical energy and gradient. Its component checks do not certify biological accuracy. <a href="SPARSE-NEWTON.html">Current finer-run status and sparse Hessian proof</a>. Before parameter inference, a fixed-length physical-unit mapping makes the common force-scale symmetry explicit; shape identifies only scale-invariant combinations, and the full compatible parameter set is still uncomputed. <a href="PHYSICAL-PARAMETER-DOMAIN.html">Parameter domain, proof and limitations</a>. Generic nonunique mechanical fits and experiments to distinguish them are established ideas; the proposed source-specific transfer-ambiguity result remains unproved. <a href="TRANSFER-CLAIM-AUDIT.html">Exact claim and closest prior work</a>.</p>'
    body+='<h2>Joint inference starts with a precise measurement</h2><p>The source does not fully determine component aggregation, growth-reference allocation or spatial weighting. A new exact quadratic observer keeps these alternatives explicit and measures both boundaries at the same current radius. It passes analytical and saved-state checks plus an independent counterexample/integral review. <a href="QUADRATIC-ENDPOINT-OBSERVER.html">Observer proof and API</a>; <a href="ENDPOINT-OBSERVER-INDEPENDENT-REVIEW.html">independent geometry example</a>.</p><img src="assets/endpoint_counterexample.png" alt="One synthetic geometry gives different material-paired, disk-mean, line-mean and maximum shortenings"><p>The joint constraint evaluator retains all 68 small-region entries and can test a conservative unknown permutation of intact apical/basal pairs with matching/Hall certificates. None of this supplies a missing noise model. Initial exact surrogate gain fits hit the table boundary. A versioned expansion to strength 20 now supplies four interior surrogate candidates under independently checked exact certificates. All 68 distinct nonlinear targets are now independently verified; the four candidates require 5.38–6.25 µm worst-case discrepancy, and sampled surrogate/direct differences reach 0.42–0.43 µm. This is one fixed material scenario, not a full identified set or a physical global optimum. <a href="JOINT-CALIBRATION-CONSTRAINTS.html">Constraints and pairing uncertainty</a>; <a href="JOINT-INFERENCE-PROGRESS.html">current joint calculation and limitations</a>.</p>'
    body+='<h2>Original five-gate ledger</h2><table><tr><th>Gate</th><th>Execution</th><th>Scientific outcome</th></tr>'
    for gate in ledger["gates"]:
        body+='<tr><td>'+str(gate["gate"])+'</td><td>'+html.escape(gate["execution"])+'</td><td>'+html.escape(gate["scientific_outcome"])+'</td></tr>'
    body+='</table><h2>Mathematics that changes the next experiment</h2><p>A height-response slope alone does not determine cell-shape asymmetry in the local finite-height model. A paired apical/basal shape response supplies an additional identifiable ratio. This is an explicit measurement requirement, not a novelty claim.</p><img src="assets/local_identifiability.png" alt="Synthetic local identifiability calculation"><p><a href="LOCAL-INFERENCE.html">Read the derivation and independent geometric checks</a>.</p>'
    body+='<h2>Why an image label needs its own model</h2><p>The published bending label concerns a tissue plug and an empty annulus in an apical image slice. A conditional axisymmetric observer gives an exact slice-existence criterion and a 2ε bound if a uniform surface-error bound ε is supplied. Unknown slice height remains explicit. This is not a certified finite-element error estimate. <a href="SLICE-OBSERVER.html">Proof, implementation and limits</a>.</p>'
    body+='<img src="assets/slice_observer.png" alt="Same synthetic tissue surface at two image slice heights"><h2>Study documents</h2><ul>'
    for path in sorted(DOC.glob("*.md")):
        body+='<li><a href="'+path.stem+'.html">'+html.escape(path.stem.replace('-',' '))+'</a></li>'
    body+='</ul><h2>Retained verification receipts</h2><ul>'
    for path in sorted((ROOT/"evidence").glob("*.json")):
        body+='<li><a href="../evidence/'+path.name+'">'+html.escape(path.name)+'</a></li>'
    body+='</ul><p>This local dossier is a separate follow-up to the avian planar-forecast study. It does not pass the parent project’s unresolved 15-step gates. Internal independent AI checks are distinct from external expert review.</p>'
    (DOC/"index.html").write_text(shell("Controlled furrowing — five-gate evidence dossier",body),encoding="utf-8")
    print(json.dumps({"html_pages":len(list(DOC.glob('*.html'))),"landing":str((DOC/'index.html').resolve())}))


if __name__=="__main__":
    main()
